```typescript
export function getTableauUserId(): string {
  if (typeof window === 'undefined' || !window.tableau) {
    return 'dev-user';
  }
  try {
    const context = (window.tableau.extensions as unknown as {
      environment?: { context?: { user?: { name?: string } } };
    }).environment?.context;
    return context?.user?.name ?? 'unknown-user';
  } catch {
    return 'unknown-user';
  }
}

export async function initializeExtension(): Promise<void> {
  if (typeof window === 'undefined' || !window.tableau) {
    return;
  }
  if (initialized) return;
  initialized = true;
  await window.tableau.extensions.initializeAsync();
}
```

### autom9-extension/src/App.svelte (key load sequence)
```svelte
onMount(async () => {
  try {
    await initializeExtension();                          // Step 1
    const tableauUserId = getTableauUserId();             // Step 2
    sessionStore.tableauUserId = tableauUserId;

    const sessionResponse = await apiFetch('/api/sessions', {  // Step 3
      method: 'POST',
      body: JSON.stringify({ tableau_user_id: tableauUserId }),
    });
    sessionStore.sessionId = sessionResponse.data.session_id;

    statusStore.loading = true;
    const statusResponse = await apiFetch('/api/status', {     // Step 4
      headers: { 'X-Autom9-Session': sessionStore.sessionId },
    });

    statusStore.integrations = statusResponse.data.integrations.map(...)
    statusStore.loading = false;
    appStatus = 'ready';
  } catch (err) {
    statusStore.loading = false;
    errorMessage = err instanceof ApiError ? err.message : (err instanceof Error ? err.message : 'Extension failed to initialize');
    appStatus = 'error';
  }
});
```

